def main():
    import sys
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])
    ptr += 1
    k = int(input[ptr])

    if k == 0:
        print(-1)
        return

    if n == 1:
        print(0)
        return

    if k * (n - 1) % 2 != 0:
        print(-1)
        return

    m = k * (n - 1)
    print(m)
    for i in range(1, n):
        for j in range(k):
            print(i, i + j + 1)

if __name__ == '__main__':
    main()
